#include <iostream>
#include <vector>

int main() {
    std::vector<int> nums = {1, 2, 3};
    nums.push_back(4);
    for (int n : nums) {
        std::cout << n << " ";
    }
    std::cout << std::endl;
    return 0;
}

#include <iostream>

void addOne(int& n) {
    n++;
}

int main() {
    int x = 5;
    addOne(x);
    std::cout << x << std::endl;
    return 0;
}

#include <iostream>
#include <string>

class Dog {
public:
    Dog(std::string name) : name(name) {}
    void speak() { std::cout << name << " says woof" << std::endl; }
private:
    std::string name;
};

int main() {
    Dog rex("Rex");
    rex.speak();
    return 0;
}

#include <iostream>

template <typename T>
T biggest(T a, T b) {
    return a > b ? a : b;
}

int main() {
    std::cout << biggest(3, 7) << " " << biggest(2.5, 1.5) << std::endl;
    return 0;
}

#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, int> ages;
    ages["Ada"] = 36;
    ages["Lin"] = 24;
    for (const auto& pair : ages) {
        std::cout << pair.first << ": " << pair.second << std::endl;
    }
    return 0;
}
